import csv

# Read atom.csv and filter for molecules with triple bonds that contain 'p' or 'br'
triple_bond_molecules = {'TR041', 'TR377', 'TR447', 'TR499'}
target_elements = {'p', 'br'}

molecules_with_target_atoms = set()
atoms_by_molecule = {}

with open('csv/atom.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        mol_id = row['molecule_id']
        element = row['element'].lower()

        if mol_id in triple_bond_molecules:
            if mol_id not in atoms_by_molecule:
                atoms_by_molecule[mol_id] = set()
            atoms_by_molecule[mol_id].add(element)

            if element in target_elements:
                molecules_with_target_atoms.add(mol_id)

print("Molecules with triple bonds:", triple_bond_molecules)
print("Atoms per molecule:")
for mol_id, elements in sorted(atoms_by_molecule.items()):
    print(f"  {mol_id}: {elements}")
print("\nMolecules with triple bonds containing p or br:", molecules_with_target_atoms)

# Count total atoms in those molecules
total_atoms = 0
with open('csv/atom.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['molecule_id'] in molecules_with_target_atoms:
            total_atoms += 1

print(f"\nTotal atoms in molecules with triple bonds containing p or br: {total_atoms}")

